import { useState, useEffect, useRef, useCallback } from 'react'

const FAIRY_SRC = 'data:video/webm;base64,'

const GREETINGS = [
  'Oh, you actually showed up. I respect that.',
  'Welcome to my universe. Try not to break anything.',
  "You found me. I've been here the whole time.",
  'Finally! I was starting to wonder about you.',
  'Every great universe needs a fairy. You are welcome.',
  'I know every secret in this place. Ask nicely.',
  'Dzifa made this. I just live here.',
  "You made it. I never doubted you. (I doubted you a little.)",
  'The portals are open. Choose wisely.',
  'Careful, some of those districts bite.',
]
const SPIN_RESPONSES = [
  'OKAY okay -- spinning. Happy now?',
  'You tapped me twice. Bold choice.',
  'That tickles, you know.',
  'Spin complete. Medal not included.',
  "Double-tap warranty? Never heard of it.",
  'I am a fairy, not a fidget spinner.',
]

const easeOut   = t => 1 - Math.pow(1 - t, 3)
const easeIn    = t => t * t * t
const easeInOut = t => t < 0.5 ? 4*t*t*t : 1 - Math.pow(-2*t+2, 3)/2
const clamp     = (v, lo, hi) => Math.max(lo, Math.min(hi, v))
const lerp      = (a, b, t) => a + (b - a) * t

const DW = 160, DH = 222

// Build the Disney-style choreographed flight sequence
function buildSequence(vw, vh) {
  const restX = vw * 0.12
  const restY = vh * 0.70
  return [
    {
      // Fly in fast from off-right, sweeping arc across top
      dur: 2.2, label: 'entry',
      pos: t => ({
        x: lerp(vw + DW, vw * 0.52, easeOut(t)),
        y: lerp(vh * 0.22, vh * 0.40, easeInOut(t)),
      }),
      tilt: t => lerp(-30, -6, easeOut(t)),
    },
    {
      // Decelerate mid-screen, sparkle burst
      dur: 1.3, label: 'burst',
      pos: t => ({
        x: lerp(vw * 0.52, vw * 0.36, easeOut(t)),
        y: lerp(vh * 0.40, vh * 0.48, easeInOut(t)),
      }),
      tilt: t => lerp(-6, 6, easeInOut(t)),
      burst: true,
    },
    {
      // Glide down to settle
      dur: 1.0, label: 'settle',
      pos: t => ({
        x: lerp(vw * 0.36, restX, easeInOut(t)),
        y: lerp(vh * 0.48, restY, easeInOut(t)),
      }),
      tilt: t => lerp(6, 0, easeOut(t)),
    },
    {
      // Hover — clickable, gentle bob
      dur: 5.5, label: 'hover',
      pos: t => ({
        x: restX + Math.sin(t * Math.PI * 2.2) * 7,
        y: restY + Math.sin(t * Math.PI * 4.4) * 6,
      }),
      tilt: t => Math.sin(t * Math.PI * 2.8) * 3,
    },
    {
      // Sweep back off right
      dur: 1.5, label: 'exit',
      pos: t => ({
        x: lerp(restX, vw + DW, easeIn(t)),
        y: lerp(restY, vh * 0.28, easeInOut(t)),
      }),
      tilt: t => lerp(0, -38, easeIn(t)),
    },
  ]
}

// Physics sparkles
let sid = 0
function makeSparkles(x, y, burst) {
  const n = burst ? 32 : 1
  return Array.from({ length: n }, () => {
    const a = Math.random() * Math.PI * 2
    const spd = burst ? 2.5 + Math.random() * 5 : 0.4 + Math.random() * 1.5
    return {
      id: sid++, x, y,
      vx: Math.cos(a) * spd,
      vy: Math.sin(a) * spd - (burst ? 2.5 : 0),
      life: 1,
      decay: burst ? 0.016 + Math.random() * 0.012 : 0.022 + Math.random() * 0.018,
      size: burst ? 3 + Math.random() * 9 : 1.5 + Math.random() * 4,
      color: ['#D4AF37','#FFE066','#ffffff','#F5C842','#FFF8DC','#ADFFD4'][Math.floor(Math.random()*6)],
      tw: Math.random() * Math.PI * 2,
    }
  })
}

export default function FairyCompanion({ musicEnabled, onMusicToggle }) {
  const [visible,  setVisible]  = useState(false)
  const [bubble,   setBubble]   = useState(null)
  const [spinning, setSpinning] = useState(false)
  const [sparkles, setSparkles] = useState([])
  const [pos,      setPos]      = useState({ x: -500, y: -500 })
  const [phase,    setPhase]    = useState('entry')

  const wrapRef     = useRef(null)
  const animRaf     = useRef(null)
  const spinning_   = useRef(false)
  const spinAngle   = useRef(0)
  const seqRef      = useRef(null)
  const phaseIdx    = useRef(0)
  const phaseT      = useRef(0)
  const burstDone   = useRef(false)
  const sparklesRef = useRef([])
  const prevTime    = useRef(null)
  const prevX       = useRef(null)
  const bubbleTimer = useRef(null)

  useEffect(() => { spinning_.current = spinning }, [spinning])
  useEffect(() => {
    const t = setTimeout(() => setVisible(true), 800)
    return () => clearTimeout(t)
  }, [])

  // Flight + sparkle loop
  useEffect(() => {
    const tick = now => {
      if (!prevTime.current) prevTime.current = now
      const dt = Math.min((now - prevTime.current) / 1000, 0.05)
      prevTime.current = now

      const vw = window.innerWidth
      const vh = window.innerHeight

      if (!seqRef.current) seqRef.current = buildSequence(vw, vh)
      const seq = seqRef.current
      const ph  = seq[phaseIdx.current]
      phaseT.current += dt

      if (phaseT.current >= ph.dur) {
        phaseIdx.current = (phaseIdx.current + 1) % seq.length
        phaseT.current   = 0
        burstDone.current = false
        seqRef.current   = buildSequence(vw, vh)
        setPhase(seq[phaseIdx.current].label)
      }

      const cur  = seq[phaseIdx.current]
      const t01  = clamp(phaseT.current / cur.dur, 0, 1)
      const p    = cur.pos(t01)
      const tilt = cur.tilt(t01)

      // Sparkle burst
      if (cur.burst && t01 > 0.4 && !burstDone.current) {
        burstDone.current = true
        sparklesRef.current = [...sparklesRef.current, ...makeSparkles(p.x, p.y, true)]
      }
      // Trail during flight
      if ((cur.label === 'entry' || cur.label === 'exit') && Math.random() < 0.55) {
        sparklesRef.current = [...sparklesRef.current, ...makeSparkles(p.x, p.y, false)]
      }

      // Update sparkle physics
      sparklesRef.current = sparklesRef.current
        .map(s => ({ ...s,
          x: s.x + s.vx, y: s.y + s.vy,
          vy: s.vy + 0.09, vx: s.vx * 0.97,
          life: s.life - s.decay, tw: s.tw + 0.18,
        }))
        .filter(s => s.life > 0)
      setSparkles([...sparklesRef.current])

      // Spin
      let spinY = 0
      if (spinning_.current) {
        spinAngle.current = (spinAngle.current + dt * 440) % 360
        spinY = spinAngle.current
      } else {
        spinAngle.current = 0
      }

      // Face direction of travel
      const dx = p.x - (prevX.current ?? p.x)
      prevX.current = p.x
      const flipX = dx < -0.3 ? -1 : 1

      setPos(p)
      if (wrapRef.current) {
        const el = wrapRef.current
        el.style.left = (p.x - DW / 2) + 'px'
        el.style.top  = (p.y - DH / 2) + 'px'
        el.style.transform = [
          'scaleX(' + flipX + ')',
          'rotate(' + tilt + 'deg)',
          'rotateY(' + spinY + 'deg)',
        ].join(' ')
      }

      animRaf.current = requestAnimationFrame(tick)
    }
    animRaf.current = requestAnimationFrame(tick)
    return () => cancelAnimationFrame(animRaf.current)
  }, [])

  const dismiss = useCallback(() => {
    clearTimeout(bubbleTimer.current)
    bubbleTimer.current = setTimeout(() => { setSpinning(false); setBubble(null) }, 4200)
  }, [])

  const handleClick = useCallback(e => {
    e.stopPropagation()
    if (spinning_.current) return
    setBubble(GREETINGS[Math.floor(Math.random() * GREETINGS.length)])
    dismiss()
  }, [dismiss])

  const handleDoubleClick = useCallback(e => {
    e.stopPropagation()
    setBubble(SPIN_RESPONSES[Math.floor(Math.random() * SPIN_RESPONSES.length)])
    setSpinning(true)
    dismiss()
  }, [dismiss])

  const isHover = phase === 'hover'

  return (
    <div style={{ position:'fixed', inset:0, pointerEvents:'none', zIndex:50 }}>

      {/* Physics sparkles */}
      {sparkles.map(s => {
        const a  = s.life * (0.6 + Math.sin(s.tw) * 0.4)
        const sz = s.size * s.life
        return (
          <div key={s.id} style={{
            position:'absolute', left:s.x - sz/2, top:s.y - sz/2,
            width:sz, height:sz, borderRadius:'50%',
            background:s.color, opacity:a,
            boxShadow:`0 0 ${sz * 2.5}px ${s.color}`,
            pointerEvents:'none',
          }}/>
        )
      })}

      {/* Fairy — mix-blend-mode: screen makes black background invisible */}
      <div
        ref={wrapRef}
        onClick={handleClick}
        onDoubleClick={handleDoubleClick}
        style={{
          position:'absolute', left:-500, top:-500,
          width:DW, height:DH,
          cursor: isHover ? 'pointer' : 'default',
          pointerEvents: isHover ? 'auto' : 'none',
          opacity: visible ? 1 : 0,
          transition: 'opacity 1.4s ease',
          willChange: 'transform, left, top',
          transformOrigin: '50% 45%',
        }}
      >
        <video
          src={FAIRY_SRC}
          autoPlay loop muted playsInline
          style={{
            width:'100%', height:'100%',
            objectFit:'cover',
            mixBlendMode:'screen',
            filter:'drop-shadow(0 0 16px rgba(212,175,55,0.7)) drop-shadow(0 0 32px rgba(212,175,55,0.3)) brightness(1.05)',
          }}
        />
      </div>

      {/* Speech bubble */}
      {bubble && (
        <div style={{
          position:'absolute',
          left: Math.min(pos.x + DW / 2 + 14, window.innerWidth - 265),
          top:  Math.max(pos.y - 85, 10),
          background:'rgba(8,7,18,0.97)',
          border:'1px solid rgba(212,175,55,0.45)',
          borderRadius:12, padding:'0.65rem 0.9rem 0.55rem',
          maxWidth:245, pointerEvents:'auto', zIndex:51,
          animation:'fairyPop 0.3s cubic-bezier(0.34,1.56,0.64,1) both',
          boxShadow:'0 4px 32px rgba(212,175,55,0.15)',
        }}>
          <div style={{
            position:'absolute', left:-7, top:22, width:0, height:0,
            borderTop:'5px solid transparent', borderBottom:'5px solid transparent',
            borderRight:'7px solid rgba(212,175,55,0.45)',
          }}/>
          <p style={{
            fontFamily:'"DM Sans",sans-serif', fontSize:'0.73rem',
            color:'rgba(245,240,232,0.93)', margin:0, lineHeight:1.65,
          }}>{bubble}</p>
          <button
            onClick={e => { e.stopPropagation(); onMusicToggle && onMusicToggle() }}
            style={{
              marginTop:'0.5rem', display:'flex', alignItems:'center', gap:'0.3rem',
              fontFamily:'"DM Mono",monospace', fontSize:'0.58rem', letterSpacing:'0.05em',
              color: musicEnabled ? '#D4AF37' : 'rgba(245,240,232,0.3)',
              background:'none', border:'none', cursor:'pointer', padding:0,
              transition:'color 0.25s ease',
            }}
          >
            <svg width="11" height="11" viewBox="0 0 12 12" fill="currentColor">
              <path d="M4.5 10a1.5 1.5 0 1 1-3 0 1.5 1.5 0 0 1 3 0zM4.5 1.8v6.8L11 7V.3L4.5 1.8z"/>
            </svg>
            {musicEnabled ? 'ambient: on' : 'ambient: off'}
          </button>
        </div>
      )}

      <style>{`
        @keyframes fairyPop {
          from { opacity:0; transform:scale(0.6) translateY(8px); }
          to   { opacity:1; transform:scale(1)   translateY(0);   }
        }
      `}</style>
    </div>
  )
}